/// A proper_noun form: which cell of its declension.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A noun in a case and number.
    Form(crate::Case, crate::Number),
    /// The locative (`Rōmae`, `domī`).
    Locative(crate::Number),
}

impl Cell {
    /// Its place in a paradigm: its group's first cell, then its values
    /// counted in order, the last fastest.
    pub const fn index(self) -> usize {
        match self {
            Cell::Form(case, number) => cell::NOM_SG as usize + case as usize * 2 + number as usize,
            Cell::Locative(number) => cell::PROPER_NOUN_LOCATIVE_SG as usize + number as usize,
        }
    }
}

impl From<(crate::Case, crate::Number)> for Cell {
    fn from((case, number): (crate::Case, crate::Number)) -> Self {
        Cell::Form(case, number)
    }
}

impl From<crate::Number> for Cell {
    fn from(number: crate::Number) -> Self {
        Cell::Locative(number)
    }
}

/// A proper_noun to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProperNoun<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
    inherent: Vec<(u8, u8)>,
    full: bool,
}

impl<'w> ProperNoun<'w> {
    /// The proper_noun `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        ProperNoun {
            lemma,
            given: Vec::new(),
            inherent: Vec::new(),
            full: false,
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    /// Its gender: only declensions of words of that gender are read.
    #[must_use]
    pub fn gender(mut self, gender: crate::Gender) -> Self {
        self.inherent.push((0, gender as u8));
        self
    }

    /// Its lemma is spelled with every mark the dictionary writes, so
    /// none is hidden (without this, a lemma typed without marks may be
    /// missing some, and its forms are less sure).
    #[must_use]
    pub fn spelled_in_full(mut self) -> Self {
        self.full = true;
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &self.inherent,
            full: self.full,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The declensions it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn declension(&self) -> Vec<Reading<'static, 'static, Declension>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
